<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {knowledgeApi} from '@/api/knowledge.api';
import type {WorkspaceGrant} from '@/types/knowledge.types';
const props=defineProps<{modelValue:boolean;spaceId:string}>();
const emit=defineEmits<{"update:modelValue":[boolean];changed:[]}>();
const open=computed({get:()=>props.modelValue,set:(value:boolean)=>emit('update:modelValue',value)});
const targets=ref<{id:string;name:string;role:string}[]>([]);const grants=ref<WorkspaceGrant[]>([]);const user=ref('');const reason=ref('');const consent=ref(false);const busy=ref(false);const error=ref('');
async function load(){[targets.value,grants.value]=await Promise.all([knowledgeApi.targets().then(r=>r.data.data),knowledgeApi.grants(props.spaceId).then(r=>r.data.data)]);}
async function grant(){busy.value=true;error.value='';try{const current=grants.value.find(g=>g.user_id===user.value);grants.value=(await knowledgeApi.share(props.spaceId,{user_id:user.value,expected_version:current?.row_version||0,reason:reason.value,allow_knowledge_submission:consent.value})).data.data;emit('changed');}catch(e:any){error.value=e.response?.data?.error?.message||'共享授权未完成';}finally{busy.value=false;}}
async function revoke(row:WorkspaceGrant){busy.value=true;try{grants.value=(await knowledgeApi.revoke(props.spaceId,{user_id:row.user_id,expected_version:row.row_version,reason:'所有者撤回资料授权',allow_knowledge_submission:false})).data.data;emit('changed');}finally{busy.value=false;}}
watch(()=>props.modelValue,async(value)=>{if(value){error.value='';user.value='';reason.value='';consent.value=false;await load();}});
</script>
<template><el-dialog v-model="open" title="授权共享资料" width="750px" append-to-body><el-alert title="共享只授予查阅权限。接收者不能修改原资料，也不会因此自动发布组织知识。" type="info" :closable="false"/><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-form label-position="top" class="share-form"><el-form-item label="同组织接收者"><el-select v-model="user" filterable><el-option v-for="target in targets" :key="target.id" :label="target.name" :value="target.id"/></el-select></el-form-item><el-form-item label="共享目的" required><el-input v-model="reason" type="textarea" :rows="2"/></el-form-item><el-checkbox v-model="consent">另行允许接收者选取片段提交知识核验及组织共享申请</el-checkbox><el-button type="primary" :disabled="!user||reason.trim().length<4" :loading="busy" @click="grant">保存只读授权</el-button></el-form><el-table :data="grants"><el-table-column label="接收者"><template #default="{row}">{{ targets.find(t=>t.id===row.user_id)?.name || row.user_id }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{ row.status==='active'?'已授权':'已撤回' }}</template></el-table-column><el-table-column label="候选提交" width="110"><template #default="{row}">{{ row.allow_knowledge_submission?'另行允许':'仅可查阅' }}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="row.status==='active'" link type="danger" @click="revoke(row)">撤回授权</el-button></template></el-table-column></el-table></el-dialog></template>
<style scoped>.share-form{display:flex;flex-direction:column;gap:12px;margin:18px 0}.share-form .el-select{width:100%}.share-form .el-button{align-self:start}</style>
